import json,re,glob
for p in sorted(glob.glob('*.jsonl')):
    ts=[]; users=0; tools=0
    for line in open(p):
        d=json.loads(line)
        if d.get('role')=='user': users+=1
        for part in (d.get('message') or {}).get('content',[]) if isinstance(d.get('message'),dict) else []:
            if part.get('type')=='tool_use': tools+=1
            if part.get('type')=='text':
                ts+=re.findall(r'<timestamp>(.*?)</timestamp>', part['text'])
    print(f'{p:36} user_turns={users:3} tools={tools:4} first={ts[0] if ts else \"-\"} last={ts[-1] if ts else \"-\"}')
